        let json = serde_json::to_string_pretty(&output).unwrap();
        assert!(json.contains("\"intent_id\""));
        assert!(json.contains("intent-abc"));
        assert!(json.contains("\"confirmation_required\""));
        assert!(json.contains("true"));
    }
}

